// ─────────────────────────────────────────────────────────────────
// Build a Google Sheets batchUpdate payload.
// One API call updates ALL rows in this batch — not one call per row.
// This avoids the Google Sheets write quota (300 req/min) entirely.
// ─────────────────────────────────────────────────────────────────

// ── Adjust these if your Users sheet columns are in a different order ──
const STATUS_COL    = 'B'; // column containing 'status'
const TIMESTAMP_COL = 'C'; // column containing 'timestamp'
const ERROR_COL     = 'D'; // column containing 'error'
const SHEET_TAB     = 'Users';
const SPREADSHEET_ID = 'YOUR_SPREADSHEET_ID'; // ← replace this
// ──────────────────────────────────────────────────────────────────

const discordResults = $input.all();
const loopItems      = $('🔁 Loop (50 users)').all(); // original items for this batch
const timestamp      = new Date().toISOString();

const data = discordResults.map((result, i) => {
  const original = loopItems[i]?.json ?? {};
  const rowNum   = original.row_number;
  const hasError = !!result.json.error;

  return {
    range:  `${SHEET_TAB}!${STATUS_COL}${rowNum}:${ERROR_COL}${rowNum}`,
    values: [[
      hasError ? 'failed' : 'done',
      timestamp,
      hasError ? String(result.json.error).substring(0, 200) : ''
    ]]
  };
});

return [{
  json: {
    spreadsheetId: SPREADSHEET_ID,
    body: JSON.stringify({ valueInputOption: 'RAW', data })
  }
}];
